@property --ring-angle { syntax: "<angle>"; inherits: true; initial-value: 0deg; }
@keyframes ring-spin { to { --ring-angle: 360deg; } }
:root { animation: ring-spin 1.6s linear infinite; }
.ring::after { background: conic-gradient(from var(--ring-angle), red); }

@property --ring-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes ring-spin { to { --ring-angle: 360deg; } }
.ring::after { animation: ring-spin 1.6s linear infinite; background: conic-gradient(from var(--ring-angle), red); }

@property --ring-angle { syntax: "<angle>"; inherits: false; initial-value: 0deg; }
@keyframes ring-spin { to { --ring-angle: 360deg; } }
.host { --ring-conic: conic-gradient(from var(--ring-angle), red); }
.host .line { background-image: var(--ring-conic); animation: ring-spin 1.6s linear infinite; }

@property --ring-opacity { syntax: "<number>"; inherits: false; initial-value: 1; }
@keyframes ring-pulse { 50% { --ring-opacity: 0.5; } }
@utility border-ring {
  &::after {
    opacity: var(--ring-opacity);
    animation: ring-pulse 1.6s ease-in-out infinite;
  }
  @media (prefers-reduced-motion: reduce) {
    &::after {
      animation: none;
      opacity: 1;
    }
  }
}

